def distinct_even_odd_palindromes(arr):
    """
    Given a list of positive integers `arr`, return a tuple (even_count, odd_count)
    where even_count is the number of distinct even integer palindromes in `arr`,
    and odd_count is the number of distinct odd integer palindromes in `arr`.
    """
    def is_palindrome(x):
        return str(x) == str(x)[::-1]
    even = 0
    odd = 0
    seen = set()
    for x in arr:
        if x not in seen and is_palindrome(x):
            seen.add(x)
            if x % 2 == 0:
                even += 1
            else:
                odd += 1
    return (even, odd)

def eat(number, need, remaining):
    if need <= remaining:
        return [number + need, remaining - need, False]
    else:
        return [number + remaining, 0, True]

def encode(message):
    vowels = set('aeiouAEIOU')
    swapped = message.swapcase()
    result = []
    for ch in swapped:
        if ch in vowels:
            base = ord('a') if ch.islower() else ord('A')
            new_ch = chr((ord(ch) - base + 2) % 26 + base)
        else:
            new_ch = ch
        result.append(new_ch)
    return ''.join(result)

def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        digits = [int(d) for d in s]
        if n < 0:
            digits[0] *= -1
        return sum(digits)

    return sorted(nums, key=lambda x: (digit_sum(x), -x))

def tri(n):
    if n == 0:
        return [0]
    elif n == 1:
        return [0, 1]
    res = [0, 1]
    for i in range(2, n+1):
        if i % 2 == 0:
            res.append(2 + i // 2)
        else:
            res.append(res[-1] + res[-2] + res[-3])
    return res

import re

def fruit_distribution(s, n):
    numbers = [int(x) for x in re.findall(r'\d+', s)]
    return n - sum(numbers)

import re
def is_bored(S):
    sentences = re.split(r'[.?!]\s*', S)
    return sum(1 for sentence in sentences if re.match(r'\bI\b', sentence.strip()))

def tri(n):
    if n == 0:
        return [2]
    tri_list = [0] * (n + 1)
    tri_list[0] = 2
    tri_list[1] = 3
    for i in range(2, n + 1):
        if i % 2 == 0:
            tri_list[i] = 2 + i // 2
        else:
            tri_list[i] = tri_list[i-1] + tri_list[i-2] + (2 + (i + 1) // 2)
    return tri_list

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current = []
    depth = 0
    for ch in paren_string:
        if ch == '(':
            depth += 1
            current.append(ch)
        elif ch == ')':
            if depth == 0:
                return []
            depth -= 1
            current.append(ch)
            if depth == 0:
                result.append(''.join(current))
                current = []
    if depth != 0:
        return []
    return result

